const body = $json.body || $json;

const isAuthenticated = !!(body.user_context && body.user_context.is_authenticated);
const authToken = body.auth_token || '';
const userMessage = body.message;
const sessionId = body.session_id || 'unknown';

const systemPrompt = `Tu es l'agent de gestion des annonces de Darimmo, une plateforme marocaine d'annonces immobilieres.

Ton role : aider un utilisateur AUTHENTIFIE a creer, modifier, supprimer ou consulter ses propres annonces.

Regles strictes :
- N'invente aucune information sur une annonce. Toute information doit venir du resultat d'un outil.
- Pour update_listing et delete_listing : n'agis JAMAIS sans un identifiant d'annonce explicite (annonce_id). Si l'utilisateur dit "mon annonce" sans preciser laquelle, utilise my_listings d'abord et demande de preciser.
- Pour delete_listing : ne mets confirmed=true QUE si l'utilisateur a explicitement confirme la suppression dans son message (ex: "oui, supprime-la", "confirme"). Sinon mets confirmed=false et pose la question de confirmation dans ta reponse texte, SANS appeler l'outil delete_listing.
- Pour create_listing : si des champs obligatoires manquent (titre, ville, type de bien, prix, surface), demande-les avant d'appeler l'outil.
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

const tools = [
  {
    name: "create_listing",
    description: "Cree une nouvelle annonce immobiliere pour l'utilisateur connecte.",
    parameters: {
      type: "OBJECT",
      properties: {
        title: { type: "STRING" },
        description: { type: "STRING" },
        property_type: { type: "STRING", enum: ["villa","appartement","riad","maison","terrain"] },
        transaction_type: { type: "STRING", enum: ["vente","location"] },
        city: { type: "STRING" },
        price: { type: "NUMBER" },
        surface: { type: "NUMBER" },
        bedrooms: { type: "NUMBER" },
        bathrooms: { type: "NUMBER" }
      },
      required: ["title","description","property_type","transaction_type","city","price","surface"]
    }
  },
  {
    name: "update_listing",
    description: "Modifie une annonce existante appartenant a l'utilisateur connecte. Fournir uniquement les champs a modifier.",
    parameters: {
      type: "OBJECT",
      properties: {
        annonce_id: { type: "NUMBER" },
        title: { type: "STRING" },
        description: { type: "STRING" },
        price: { type: "NUMBER" },
        surface: { type: "NUMBER" },
        bedrooms: { type: "NUMBER" },
        bathrooms: { type: "NUMBER" }
      },
      required: ["annonce_id"]
    }
  },
  {
    name: "delete_listing",
    description: "Supprime une annonce appartenant a l'utilisateur connecte. Necessite une confirmation explicite de l'utilisateur dans le message.",
    parameters: {
      type: "OBJECT",
      properties: {
        annonce_id: { type: "NUMBER" },
        confirmed: { type: "BOOLEAN" }
      },
      required: ["annonce_id","confirmed"]
    }
  },
  {
    name: "my_listings",
    description: "Liste toutes les annonces de l'utilisateur connecte.",
    parameters: { type: "OBJECT", properties: {} }
  }
];

return {
  json: {
    is_authenticated: isAuthenticated,
    auth_token: authToken,
    original_user_message: userMessage,
    session_id: sessionId,
    gemini_request_body: {
      contents: [{ role: "user", parts: [{ text: `${systemPrompt}\n\nMessage de l'utilisateur : "${userMessage}"` }] }],
      tools: [{ functionDeclarations: tools }]
    }
  }
};

return {
  json: {
    reply: "Vous devez etre connecte pour gerer vos annonces (creer, modifier, supprimer ou consulter). Merci de vous connecter puis de reessayer.",
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "account_help",
    metadata: { agent_used: "listing_management_agent", tool_calls_count: 0, llm_calls_count: 0 }
  }
};

const prevData = $('Build Prompt And Tools').item.json;
const candidate = $json.candidates[0];
const parts = candidate.content.parts;
const functionCallPart = parts.find(p => p.functionCall);

if (!functionCallPart) {
  const textPart = parts.find(p => p.text);
  return {
    json: {
      needs_tool_call: false,
      direct_reply: textPart ? textPart.text : "Je n'ai pas compris votre demande.",
      session_id: prevData.session_id
    }
  };
}

const toolName = functionCallPart.functionCall.name;
const args = functionCallPart.functionCall.args;
const authToken = prevData.auth_token;

let django_method = 'GET';
let django_url = '';
let django_body = {};

if (toolName === 'create_listing') {
  django_method = 'POST';
  django_url = 'http://127.0.0.1:8000/api/annonces/';
  django_body = {
    title: args.title,
    description: args.description,
    property_type: args.property_type,
    transaction_type: args.transaction_type,
    city: args.city,
    price: args.price,
    surface: args.surface,
    bedrooms: args.bedrooms || 0,
    bathrooms: args.bathrooms || 0
  };
} else if (toolName === 'update_listing') {
  django_method = 'PATCH';
  django_url = 'http://127.0.0.1:8000/api/annonces/' + args.annonce_id + '/';
  django_body = {};
  ['title','description','price','surface','bedrooms','bathrooms'].forEach(f => {
    if (args[f] !== undefined) django_body[f] = args[f];
  });
} else if (toolName === 'delete_listing') {
  if (!args.confirmed) {
    return {
      json: {
        needs_tool_call: false,
        direct_reply: `Confirmez-vous la suppression de l'annonce ${args.annonce_id} ? Cette action est irreversible. Repondez "oui, confirme" pour valider.`,
        session_id: prevData.session_id
      }
    };
  }
  django_method = 'DELETE';
  django_url = 'http://127.0.0.1:8000/api/annonces/' + args.annonce_id + '/';
  django_body = {};
} else if (toolName === 'my_listings') {
  django_method = 'GET';
  django_url = 'http://127.0.0.1:8000/api/annonces/mes_annonces/';
  django_body = {};
}

return {
  json: {
    needs_tool_call: true,
    tool_name: toolName,
    tool_args: args,
    django_method,
    django_url,
    django_body,
    auth_token: authToken,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

return {
  json: {
    reply: $json.direct_reply,
    session_id: $json.session_id,
    recommended_annonce_ids: [],
    intent: "account_help",
    metadata: { agent_used: "listing_management_agent", tool_calls_count: 0, llm_calls_count: 1 }
  }
};

const prevData = $('Extraire functionCall et preparer requete Django').item.json;
const djangoResult = $json;

// Si le résultat est une liste paginée (results) ou une liste directe,
// on extrait les IDs des annonces pour les renvoyer au frontend.
let annonceIds = [];
const resultsArray = djangoResult.results || (Array.isArray(djangoResult) ? djangoResult : null);
if (resultsArray && Array.isArray(resultsArray)) {
  annonceIds = resultsArray.map(a => a.id).filter(id => id !== undefined);
}

return {
  json: {
    tool_name: prevData.tool_name,
    tool_result: djangoResult,
    annonce_ids: annonceIds,
    original_user_message: prevData.original_user_message,
    session_id: prevData.session_id
  }
};

const d = $json;

const prompt = `Tu es l'agent de gestion des annonces de Darimmo.

Outil appele : ${d.tool_name}
Resultat retourne par l'API : ${JSON.stringify(d.tool_result)}

Message original de l'utilisateur : "${d.original_user_message}"

Regles strictes :
- Base ta reponse UNIQUEMENT sur le resultat fourni ci-dessus. N'invente rien.
- Si le resultat contient une erreur (ex: 403, 404, permission refusee), explique clairement a l'utilisateur qu'il n'a pas acces a cette annonce ou qu'elle n'existe pas, sans detailler la cause technique.
- Si l'action a reussi, confirme-le clairement (annonce creee/modifiee/supprimee, ou liste des annonces trouvees).
- Reponds TOUJOURS dans la meme langue que le message de l'utilisateur. Si l'utilisateur ecrit en darija (arabe marocain, en caracteres latins ou arabes), en arabe standard, en francais ou en anglais, reponds dans cette meme langue.`;

return {
  json: {
    gemini_request_body: { contents: [{ role: "user", parts: [{ text: prompt }] }] },
    session_id: d.session_id,
    tool_result: d.tool_result
  }
};

const replyText = $json.candidates[0].content.parts[0].text;
const prevData = $('Construire prompt final').item.json;

return {
  json: {
    reply: replyText,
    session_id: prevData.session_id,
    recommended_annonce_ids: $('Reformater le resultat Django').item.json.annonce_ids,
    intent: "listing_management",
    metadata: { agent_used: "listing_management_agent", tool_calls_count: 1, llm_calls_count: 2 }
  }
};
